tool_input.new_string:
const curYld = (cfgDps && price > 0) ? cfgDps / price * 100 : null;
const avg = _mMean(histY);
// 目标股息率：动态 = 近3年均值 + 安全垫，且不低于全局下限；无历史则退回固定 targetYld
const fixedYld = params.targetYld || 5.0;
const pad = params.yldPadPct != null ? params.yldPadPct : 1.0;      // 安全垫（百分点）
const floor = params.targetYldFloor != null ? params.targetYldFloor : fixedYld; // 下限
const mode = params.targetYldMode || 'dynamic';
let targetYld = fixedYld, targetYldConst = '固定 ' + fmt(fixedYld, 1) + '%';
if (mode === 'dynamic' && avg != null && avg > 0) {
  const raw = avg + pad;
  if (raw >= floor) {
    targetYld = raw;
    targetYldConst = '均值 ' + fmt(avg, 1) + '+垫 ' + fmt(pad, 1);
  } else {
    targetYld = floor;
    targetYldConst = '下限兜底 ' + fmt(floor, 1) + '%（均值仅 ' + fmt(avg, 1) + '）';
  }
}
targetYld = +targetYld.toFixed(4);
return {
  code: t.code, name: t.name, asOf: lastDate, price: +price.toFixed(4),
  dps: cfgDps, targetYld: targetYld, targetYldMode: mode, targetYldConst: targetYldConst,
  curYld: curYld != null ? +curYld.toFixed(4) : null,
  yldAvg: avg != null ? +avg.toFixed(4) : null,
  yldPct: _mPctRank(histY, curYld), histYldN: histY.length,
  targetBuyAbsolute: (cfgDps && targetYld > 0) ? +(cfgDps / (targetYld / 100)).toFixed(3) : null,
  targetBuyConservative: (cfgDps && avg > 0) ? +(cfgDps / (avg * 1.1 / 100)).toFixed(3) : null,
  boll: boll
};

