const mode = params.targetYldMode || 'dynamic';
let targetYld = fixedYld;
if (mode === 'dynamic' && avg != null && avg > 0) {
  targetYld = Math.max(floor, avg + pad);
}
targetYld = +targetYld.toFixed(4);
return {
  code: t.code, name: t.name, asOf: lastDate, price: +price.toFixed(4),
  dps: cfgDps, targetYld: targetYld, targetYldMode: mode,
  curYld: curYld != null ? +curYld.toFixed(4) : null,
  yldAvg: avg != null ? +avg.toFixed(4) : null,
  yldPct: _mPctRank(histY, curYld), histYldN: histY.length,
  targetBuyAbsolute: (cfgDps && targetYld > 0) ? +(cfgDps / (targetYld / 100)).toFixed(3) : null,
  targetBuyConservative: (cfgDps && avg > 0) ? +(cfgDps / (avg * 1.1 / 100)).toFixed(3) : null,
  boll: boll
};

