function renderAlerts(rows, T) {
  const out = [];
  // 数据完整度：缺治理/时序字段会导致宪法条款无法校验，必须显式红条提醒（避免「没标红=没问题」的误判）
  const targetsNeedGov = rows.filter(r => r.w > 0 && r.t);
  const missGov = targetsNeedGov.filter(r => !r.t.governance).map(r => r.name);
  const missOcf = targetsNeedGov.filter(r => !(Array.isArray(r.t.ocfd2y) && r.t.ocfd2y.length >= 2)).map(r => r.name);
  if (missGov.length)
    out.push(['bad', '×', '数据完整度：' + missGov.length + ' 只目标缺 governance 字段（' + missGov.join('、') + '），宪法第一条无法校验——请在 config/选股脚本补齐。']);
  if (missOcf.length)
    out.push(['bad', '×', '数据完整度：' + missOcf.length + ' 只目标缺 ocfd2y/payout2y（' + missOcf.join('、') + '），「连续两年」规则无法校验——请在 config/选股脚本补齐。']);

  const stale = Object.keys(S.px).filter(k => Date.now() - S.px[k].at > 60000);
  if (stale.length) out.push(['warn', '!', '有 ' + stale.length + ' 只价格超过 1 分钟未更新，可能是休市或接口限流。']);
  if (!rows.some(r => r.shares > 0)) out.push(['ok', 'i', '当前视图还没有持仓 —— 点右上角「+ 交易」记第一笔买入。']);

