tool_input.new_string:
function renderPlan(rows, T) {
  // 增量资金优先：读「本次投入金额」输入框；空/0 则回退到 config 的 monthly_capital（旧字段 capital 兼容）
  const inEl = document.getElementById('inPlanAmount');
  const inputVal = inEl ? parseFloat(inEl.value) : NaN;
  const monthlyFallback = (+RULES.monthly_capital) || (+RULES.capital) || 0;
  const amount = (isFinite(inputVal) && inputVal > 0) ? inputVal : monthlyFallback;
  $('#planHead').textContent = amount
    ? fmt(amount, 0) + ' 元 · 本次投入' + ((isFinite(inputVal) && inputVal > 0) ? '（手动）' : '（默认月度增量）')
    : '未配置本金';
  const body = $('#planBody'), note = $('#planNote');
  const COLS = 9;
  const hasMargin = rows.some(r => r.margin);
  if (!amount) { body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">请在上面填写本次投入金额，或让 config.js 给出 rules.monthly_capital。</td></tr>'; return; }
  if (!rows.length) {
    body.innerHTML = '<tr><td colspan="' + COLS + '" class="dim" style="text-align:center;padding:16px">先记一笔买入，或等 config.js 生成目标清单。</td></tr>';
