// #10 文件损坏应急：用浏览器缓存（IndexedDB mirror）里最近的镜像恢复
$('#btnDbRestore').onclick = async () => {
  if (!confirm('用浏览器缓存里的最近镜像恢复当前数据？\n（文件损坏时的应急入口；会用缓存覆盖当前内存库）')) return;
  try {
    const mirror = await idbGet('mirror');
    if (!mirror || !mirror.bytes) { toast('浏览器缓存里没有可恢复的镜像', true); return; }
    const bytes = mirror.bytes instanceof Uint8Array ? mirror.bytes : new Uint8Array(mirror.bytes);
    const d = openDbFromBytes(bytes);
    if (!dbHasData(d)) seedInto(d);
    db = d;
    dbFile.name = mirror.name || dbFile.name;
    dbFile.size = bytes.length; dbFile.savedAt = mirror.at || 0;
    dbStale = !!dbFile.handle;
    readState(); startApp();
    $('#maskSet').classList.remove('show');
    toast('已从浏览器缓存恢复（' + new Date(mirror.at || Date.now()).toLocaleString('zh-CN', { hour12: false }) + '）');
  } catch (e) { toast('恢复失败：' + e.message, true); }
};

